<script setup lang="ts">
defineProps<{ results: any[]; zipProgress?: number; zipping?: boolean }>()
defineEmits<{ select: [item:any]; download: [item:any]; fullscreen:[item:any]; zip: [] }>()
function time(v: any) { return new Intl.DateTimeFormat('id-ID', { hour:'2-digit', minute:'2-digit' }).format(new Date(v || Date.now())) }
</script>
<template><section class="card recent-card"><div class="card-heading compact"><div><h2>Hasil Terbaru</h2><p>Foto dari sesi ini, tersimpan lokal di perangkat.</p></div><button class="btn btn-secondary" :disabled="!results.length || zipping" @click="$emit('zip')"><AppIcon name="download" />{{ zipping ? `Membuat ZIP ${zipProgress || 0}%` : 'Unduh Semua ZIP' }}</button></div><div v-if="results.length" class="recent-grid"><article v-for="item in results.slice(0, 12)" :key="item.id" class="result-tile" @dblclick="$emit('fullscreen', item)"><button class="thumb" :aria-label="`Pilih ${item.fileName}`" @click="$emit('select', item)"><img v-if="item.objectUrl || item.url || item.thumbnailUrl" :src="item.thumbnailUrl || item.objectUrl || item.url" :alt="item.fileName"><span v-else><AppIcon name="image" /></span></button><div class="tile-meta"><span><strong :title="item.fileName">{{ item.fileName }}</strong><small>{{ time(item.createdAt) }} · {{ item.status || 'success' }}</small></span><button class="btn btn-icon btn-ghost" :aria-label="`Unduh ${item.fileName}`" @click="$emit('download', item)"><AppIcon name="download" :size="16" /></button></div></article></div><div v-else class="empty-row"><AppIcon name="image" /><span><strong>Belum ada foto yang diproses</strong><small>Pilih foto uji atau jalankan Auto-Watch.</small></span></div></section></template>

